using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PredictionConvergenceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/PredictionConvergenceCustomDescription", order = 0)]
public class PredictionConvergenceCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private GainEffectWithMultiplierCustomDescription gainEffectWithMultiplierCustomDescription;

	[SerializeField]
	private StarRequirementCustomDescription starRequirementCustomDescription;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PredictionConvergenceAction predictionConvergenceAction = battleAction as PredictionConvergenceAction;
		string localizedString = base.localizationManager.GetLocalizedString("DiscardAllDiceFromHand");
		string text = gainEffectWithMultiplierCustomDescription.GetActionDescription(amountModified, battleAction, predictionConvergenceAction.GainAstriumAction).AddDotIfJapaneseOrKoreanOrTraditionalChinese();
		return starRequirementCustomDescription.GetRequirementLocalizedDescription() + "\n" + localizedString + "\n" + text + "\n" + base.localizationManager.GetLocalizedDrawTheSameAmount() + "\n" + predictionConvergenceAction.MoveOrbsAction.GetActionDescription(Mathf.Abs(predictionConvergenceAction.MoveOrbAmount));
	}
}
